// decodeLoadBalancer reads lb load-balancer create's flags into the SDK's
// create details, rejecting unknown members.
func decodeLoadBalancer(command sdkcli.Command) (loadbalancer.CreateLoadBalancerDetails, error) {
	values, err := flags(command, "compartment-id", "display-name", "shape-name")
	if err != nil {
		return loadbalancer.CreateLoadBalancerDetails{}, err
	}
	isPrivate, err := boolFlag(command, "is-private")
	if err != nil {
		return loadbalancer.CreateLoadBalancerDetails{}, err
	}
	details := loadbalancer.CreateLoadBalancerDetails{CompartmentId: &values[0], DisplayName: &values[1], ShapeName: &values[2], IsPrivate: isPrivate}
	for name, target := range map[string]any{"subnet-ids": &details.SubnetIds, "network-security-group-ids": &details.NetworkSecurityGroupIds,
		"shape-details": &details.ShapeDetails, "certificates": &details.Certificates, "hostnames": &details.Hostnames,
		"backend-sets": &details.BackendSets, "listeners": &details.Listeners, "rule-sets": &details.RuleSets} {
		if err := jsonFlag(command, name, target); err != nil {
			return loadbalancer.CreateLoadBalancerDetails{}, err
		}
	}
	return details, nil
}

// createLoadBalancer submits the load balancer; it is created
// asynchronously, so the provisioner waits for it to list ACTIVE.
func createLoadBalancer(ctx context.Context, c *SDKClient, command sdkcli.Command) (any, error) {
	details, err := decodeLoadBalancer(command)
	if err != nil {
		return nil, err
	}
	client, err := c.loadBalancer()
	if err != nil {
		return nil, err
	}
	token, err := retryToken(ctx, c, command)
	if err != nil {
		return nil, err
	}
	response, err := client.CreateLoadBalancer(ociclient.RequestContext(ctx), loadbalancer.CreateLoadBalancerRequest{OpcRetryToken: token, CreateLoadBalancerDetails: details})
	return map[string]any{"work-request-id": response.OpcWorkRequestId}, err
}

func (c *Client) Call(ctx context.Context, args []string) (data jsontext.Value, handled bool, err error) {
	command, err := Parse(args)
	if err != nil {
		return nil, false, err
	}
	if _, ok := command.Flags["output"]; ok {
		return nil, false, errors.New("OCI --output is fixed to json")
	}
	if _, ok := command.Flags["region"]; ok {
		return nil, false, errors.New("OCI --region is selected by the caller")
	}
	handler, ok := handlers[command.Path]
	if !ok {
		return nil, false, fmt.Errorf("%w: %s", ErrUnsupported, command.Path)
	}
	value, err := handler(ociclient.RequestContext(ctx), c, command)
	if err != nil {
		return nil, true, fmt.Errorf("OCI read failed: %s: %w", command.Path, err)
	}
	if unused := command.unused(); len(unused) > 0 {
		// The read ignored a flag, so its result may be wider than asked
		// for. Report the command as unsupported rather than answer it.
		return nil, false, fmt.Errorf("%w: %s with --%s", ErrUnsupported, command.Path, strings.Join(unused, ", --"))
	}
	data, err = Render(value)
	return data, true, err
}

// Render marshals an SDK value and rewrites member names to the CLI's
// kebab-case. Members of user-keyed maps keep their keys.
func Render(value any) (jsontext.Value, error) {
	wire, err := json.Marshal(value, json.FormatNilSliceAsNull(true))
	if err != nil {
		return nil, fmt.Errorf("encode OCI response: %w", err)
	}
	return kebab(jsontext.Value(wire), false)
}

